    @Test("DAG-079 equality ignores the order")
    func dag079() throws {
        // DirectedPseudograph; V [0, 1]; E [] / insert(edge: 1→0) / remove(edge: 1→0) / == DirectedAcyclicGraph<DirectedPseudograph>(vertices: [0, 1], edges: [])
        var graph = try #require(DirectedAcyclicGraph<DirectedPseudograph<Int>>(vertices: [0, 1], edges: [] as [DirectedEdge<Int>]))
        #expect(try graph.insert(edge: DirectedEdge(from: 1, to: 0)) == 0)
        // After insert(edge: 1→0).
        #expect(Array(graph.topologicalOrder) == [1, 0])
        #expect(Array(graph.vertices) == [0, 1])
        #expect(Array(graph.edges.indices) == [0])
        #expect(Array(graph.edges) == [DirectedEdge(from: 1, to: 0)])
        #expect(graph.remove(edge: DirectedEdge(from: 1, to: 0)) == DirectedEdge(from: 1, to: 0))
        let other3 = try #require(DirectedAcyclicGraph<DirectedPseudograph<Int>>(vertices: [0, 1], edges: [] as [DirectedEdge<Int>]))
        #expect(graph == other3 && other3 == graph)
        #expect(graph.hashValue == other3.hashValue)
        // Equal although the orders differ.
        #expect(Array(graph.topologicalOrder) == [1, 0] && Array(other3.topologicalOrder) == [0, 1])
        // Final state.
        #expect(Array(graph.topologicalOrder) == [1, 0])
        #expect(Array(graph.vertices) == [0, 1])
        #expect(Array(graph.edges.indices) == [] as [Int])
        #expect(Array(graph.edges) == [] as [DirectedEdge<Int>])
